// ---- PRODUCER PREFLIGHT FAULT 1 -----------------------------------------
// The cleanup/harvest callable is DEFINED HERE, BEFORE the sampler is
// installed and before the click, so that ANY throw from the install, the
// click or the first post-click read still reaches a real function from the
// outer `finally`. Previously the assignment sat AFTER the wait loop, so a
// throw in that region left the hoisted `var` undefined, the `finally`
// skipped the harvest entirely, the captured frames were lost and the page
// kept a live rAF sampler installed.
//
// Every observation this closure reads (first valid ms, poll ms, stop reason,
// decision) is declared BEFORE it too, so no read can hit a temporal dead
// zone. Cleanup (stop + delete) is attempted on EVERY path, including when
// the harvest read itself throws, and an empty/failed harvest is recorded as
// such — never as a successful-looking capture.
var contCg = null; var contSt = null; var contUi = null;
var firstValidRuntimeMs = null;      // ms since the click, from the poll loop
var lastPollMsSinceClick = 0;
var captureDecision = null;
var captureStopReason = null;
var harvestedContinueTelemetry = null;
var harvestContinueSampler = async (why) => {
  if (harvestedContinueTelemetry) return harvestedContinueTelemetry;
  let raw = null; let harvestError = null; let cleanupError = null; let cleanedUp = false;
  try {
    raw = await page.evaluate(() => {
      const rec = window.__voxContinueSampler;
      if (!rec) return null;
      rec.stopped = true;
      const out = {
        frames: rec.frames, cap: rec.cap, capHit: rec.capHit === true,
        clickMs: rec.clickMs ?? null, frameErrors: rec.frameErrors ?? 0,
        installError: rec.installError ?? null
      };
      delete window.__voxContinueSampler;   // cleanup happens on every path
      return out;
    });
    cleanedUp = true;
  } catch (e) {
    harvestError = String(e?.message ?? e).slice(0, 200);
    // The read failed. STOP AND DELETE the sampler anyway: a failed harvest
    // may not leave a live rAF loop running on the page.
    try {
      await page.evaluate(() => {
        const rec = window.__voxContinueSampler;
        if (rec) rec.stopped = true;
        delete window.__voxContinueSampler;
        return true;
      });
      cleanedUp = true;
    } catch (e2) { cleanupError = String(e2?.message ?? e2).slice(0, 200); }
  }
  const frames = (raw?.frames ?? []).map((fr) => (raw?.clickMs == null
    ? { ...fr, msSinceClick: null }
    : { ...fr, msSinceClick: fr.ms - raw.clickMs }));
  const firstValid = typeof firstValidRuntimeMs === 'number' ? firstValidRuntimeMs : null;
  harvestedContinueTelemetry = {
    harvestedBecause: why,
    samplerPresentAtHarvest: !!raw,
    harvested: harvestError == null,
    cleanedUp,
    harvestError,
    cleanupError,
    clickMsInSamplerClock: raw?.clickMs ?? null,
    capFrames: raw?.cap ?? CONTINUE_CAPTURE.maxFrames,
    capHit: raw?.capHit ?? null,
    frameErrorCount: raw?.frameErrors ?? null,
    installError: raw?.installError ?? null,
    window: { ...CONTINUE_CAPTURE, firstValidRuntimeMs: firstValid, lastPolledMsSinceClick: lastPollMsSinceClick,
      stopReason: captureStopReason, lastDecision: captureDecision },
    // FAULT 3: backed by the ACTUAL retained frames and harvest/cap state.
    completeness: continueCaptureCompleteness({
      firstValidRuntimeMs: firstValid, lastObservedMs: lastPollMsSinceClick,
      capped: captureDecision?.capped === true,
      frames, samplerPresentAtHarvest: !!raw, harvestError,
      installError: raw?.installError ?? null, capHit: raw?.capHit ?? null
    }),
    summary: summariseContinueFrames(frames, { firstValidRuntimeMs: firstValid }),
    // EVERY retained frame, including the pre-click ones. No ms<=5000 filter.
    frames,
    note: 'no frame is filtered at harvest; an empty, capped or failed harvest is reported as incomplete and is never a pass'
  };
  try {
    writeFileSync(join(outDir, 'continue-raf-telemetry.json'), `${JSON.stringify(harvestedContinueTelemetry, null, 2)}\n`);
  } catch { /* the summary copy in report still carries it */ }
  return harvestedContinueTelemetry;
};
// ---- PASSIVE per-rAF Continue telemetry, ARMED BEFORE THE CLICK ----------

