function chooseKey(dirs, want) {
  let best = null; let bestDot = -Infinity;
  for (const [k, d] of Object.entries(dirs)) {
    if (!d) continue;
    const s = dot2(d, want);
    if (s > bestDot) { bestDot = s; best = k; }
